package slop

import (
	"path/filepath"
	"regexp"
	"strings"
)

// Vaadin builds its browser side from the Java dependency. On every build it
// writes frontend/generated/ (index.tsx, routes.tsx, flow/, jar-resources/:
// "This file is auto-generated by Vaadin", much of it Vaadin Ltd's own
// component code), generates the package.json that installs the @vaadin/*
// component packages, and defines the `Frontend/` import alias for the
// project's frontend directory. None of that is written down in a manifest
// SLOP-001 reads, so in a Vaadin project every import there looked undeclared:
// 373 SLOP-001 findings on two RealVuln repositories, all in
// src/main/frontend/generated/.
//
// A project is a Vaadin project when its pom.xml or Gradle build names a
// com.vaadin artifact outside a comment.

var (
	vaadinDepRe   = regexp.MustCompile(`\bcom\.vaadin\b`)
	jvmBuildNoise = regexp.MustCompile(`(?s)/\*.*?\*/|<!--.*?-->|(?m:^\s*//[^\n]*)`)
)

// isJVMBuild reports whether base is a Maven or Gradle build file.
func isJVMBuild(base string) bool {
	switch strings.ToLower(base) {
	case "pom.xml", "build.gradle", "build.gradle.kts":
		return true
	}
	return false
}

// declaresVaadin reports whether a JVM build file's content depends on Vaadin.
func declaresVaadin(content []byte) bool {
	return vaadinDepRe.Match(jvmBuildNoise.ReplaceAll(content, nil))
}

// isVaadinGenerated reports whether path is inside a frontend/generated/
// directory, where Vaadin writes its build output.
func isVaadinGenerated(path string) bool {
	segs := strings.Split(filepath.ToSlash(path), "/")
	for i := 0; i+1 < len(segs)-1; i++ {
		if strings.EqualFold(segs[i], "frontend") && segs[i+1] == "generated" {
			return true
		}
	}
	return false
}

// vaadinProvided reports whether an npm import is provided by Vaadin itself:
// its own @vaadin/* scope, or the Frontend/ alias it defines.
func vaadinProvided(pkg string) bool {
	return strings.HasPrefix(pkg, "@vaadin/") || pkg == "Frontend"
}
